/*
 * Static replacement for aribcc_config.h.in (normally generated by CMake).
 *
 * Local change for the SwiftPM build: the platform split is done here instead
 * of with CMake options. On Apple platforms the CoreText font provider and
 * text renderer are enabled (the renderer itself lives in the separate
 * CAribCaptionRenderer target). Everywhere else the renderer is disabled so
 * that the decoder can be built and unit tested on Linux without FreeType or
 * Fontconfig.
 */

#ifndef ARIBCAPTION_ARIBCC_CONFIG_H
#define ARIBCAPTION_ARIBCC_CONFIG_H

#define ARIBCC_VERSION          "1.1.2"
#define ARIBCC_VERSION_MAJOR    1
#define ARIBCC_VERSION_MINOR    1
#define ARIBCC_VERSION_PATCH    2

#if defined(__APPLE__)
    #define ARIBCC_USE_CORETEXT 1
#else
    #define ARIBCC_NO_RENDERER 1
#endif

#endif  // ARIBCAPTION_ARIBCC_CONFIG_H
